#include <cstddef>
#include <utility>
#include <vector>

template <typename T>
void removeUnordered(std::vector<T>& items, std::size_t index)
{
    if (index != items.size() - 1)
    {
        items[index] = std::move(items.back());
    }
    items.pop_back();
}

unitTests:
TEST("the last element fills the gap") { std::vector<int> v{ 10, 20, 30, 40, 50 }; removeUnordered(v, 1); CHECK_EQ(v, (std::vector<int>{ 10, 50, 30, 40 })); }
TEST("removing the last element") { std::vector<int> v{ 1, 2, 3 }; removeUnordered(v, 2); CHECK_EQ(v, (std::vector<int>{ 1, 2 })); }
TEST("removing the only element") { std::vector<std::string> v{ "solo" }; removeUnordered(v, 0); CHECK(v.empty()); }
TEST("works with strings") { std::vector<std::string> v{ "a", "b", "c", "d" }; removeUnordered(v, 0); CHECK_EQ(v, (std::vector<std::string>{ "d", "b", "c" })); removeUnordered(v, 2); CHECK_EQ(v, (std::vector<std::string>{ "d", "b" })); }

